/* Work OS: dynamic boards, independent from the legacy task model. */
let wsState={workspaces:[],boards:[],fields:[],items:[]},wsId=null,boardId=null,wsMode='table',wsQuery='';
const wsTypes={text:'Texto',number:'Número',date:'Data',checkbox:'Checkbox',status:'Status',relation:'Relacionamento',lookup:'Lookup · espelhamento',rollup:'Rollup · agregação',formula:'Fórmula'};
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function wsButton(label,fn,cls='plain'){const b=node('button',label,cls);b.type='button';b.onclick=fn;return b}
async function wsLoad(){try{wsState=await api('/api/workspaces');if(!wsState.workspaces.some(w=>w.id===wsId))wsId=wsState.workspaces[0]?.id??null;wsDraw()}catch(e){$('#workspaces').replaceChildren(node('p',e.message,'notice'))}}
async function wsWrite(method,data){try{const result=await api('/api/workspaces',{method,body:JSON.stringify(data)});if(data.action==='workspace')wsId=result.id;if(data.action==='board')boardId=result.id;await wsLoad();toast('Alteração salva.');return true;}catch(e){toast(e.message);await wsLoad();return false;}}
function wsSelectOptions(label,options){const wrap=node('label',label),sel=node('select');sel.required=true;for(const [key,name] of options){const opt=node('option',name);opt.value=key;sel.append(opt)}wrap.append(sel);return {wrap,sel}}
function wsFieldConfig(host,type,board){
 host.replaceChildren();const fields=wsState.fields.filter(f=>f.board_id===board);
 function select(label,options){const x=wsSelectOptions(label,options);host.append(x.wrap);return x.sel}
 const numeric=fields.filter(f=>f.type==='number').map(f=>[f.id,f.name]);
 if(type==='relation'){const target=select('Quadro de destino',wsState.boards.map(b=>[b.id,(wsState.workspaces.find(w=>w.id===b.workspace_id)?.name||'')+' / '+b.name]));return ()=>({target_board_id:Number(target.value)})}
 if(type==='formula'){const left=select('Primeiro campo numérico',numeric),op=select('Operação',[['+','Somar'],['-','Subtrair'],['*','Multiplicar'],['/','Dividir']]),right=select('Segundo campo numérico',numeric);if(!numeric.length)host.append(node('p','Crie campos numéricos antes de criar uma fórmula.','notice'));return ()=>({left_field_id:Number(left.value),right_field_id:Number(right.value),operator:op.value})}
 if(type==='lookup'||type==='rollup'){
 const links=fields.filter(f=>f.type==='relation');
 const link=select('Campo de relacionamento',links.map(f=>[f.id,f.name]));
 const agg=type==='rollup'?select('Agregação',[['count','Contagem de registros'],['sum','Soma'],['avg','Média'],['min','Mínimo'],['max','Máximo']]):null;
 const target=select('Campo do quadro relacionado',[]);
 function populate(){target.replaceChildren();const rel=links.find(f=>f.id===Number(link.value));const candidates=wsState.fields.filter(f=>f.board_id===rel?.config?.target_board_id&&(type==='rollup'?f.type==='number':['text','number','date','checkbox','status'].includes(f.type)));const options=type==='lookup'?[['title','Nome do registro'],...candidates.map(f=>[f.id,f.name])]:candidates.map(f=>[f.id,f.name]);for(const [key,name] of options){const o=node('option',name);o.value=key;target.append(o)}target.disabled=agg?.value==='count';target.required=!target.disabled;}
 link.onchange=populate;if(agg)agg.onchange=populate;populate();if(!links.length)host.append(node('p','Crie um campo Relacionamento antes de continuar.','notice'));
 return ()=>({relation_field_id:Number(link.value),target_field_id:target.value==='title'?'title':Number(target.value),...(agg?{aggregate:agg.value}:{})});
 }
 return ()=>({});
}
function wsRelationEditor(item,field){const values=new Set(item.values?.[field.id]||[]),targets=wsState.items.filter(i=>i.board_id===field.config?.target_board_id);const host=node('div',undefined,'form');for(const t of targets){const label=node('label',undefined,'check'),c=node('input');c.type='checkbox';c.checked=values.has(t.id);c.onchange=()=>{if(c.checked)values.add(t.id);else values.delete(t.id)};label.append(c,document.createTextNode(t.title));host.append(label)}if(!targets.length)host.append(node('p','Nenhum registro disponível.'));const d=node('div',undefined,'dialog');d.append(node('h2',field.name),host);const actions=node('div',undefined,'actions');actions.append(wsButton('Cancelar',closeModal));const save=wsButton('Salvar vínculos',async()=>{save.disabled=true;if(await wsWrite('PATCH',{action:'value',id:item.id,field_id:field.id,value:[...values]}))closeModal();else save.disabled=false},'primary');actions.append(save);d.append(actions);$('#modal').replaceChildren(d);$('#modal').classList.add('open')}
function wsCreate(action,extra={}){const modal=$('#modal'),d=node('div',undefined,'dialog'),form=node('form',undefined,'form'),name=node('input');name.required=true;name.maxLength=120;name.placeholder='Nome';const names={workspace:'Novo workspace',board:'Novo quadro',field:'Novo campo',item:'Novo registro',rename:'Renomear registro',group:'Novo grupo'};d.append(node('h2',names[action]));form.append(name);let type,readConfig=()=>({});if(action==='field'){type=node('select');for(const [k,v] of Object.entries(wsTypes)){const o=node('option',v);o.value=k;type.append(o)}form.append(type);const configHost=node('div',undefined,'form');form.append(configHost);const configure=()=>{readConfig=wsFieldConfig(configHost,type.value,extra.board_id)};type.onchange=configure;configure()}const actions=node('div',undefined,'actions');actions.append(wsButton('Cancelar',closeModal));const save=node('button','Salvar','primary');save.type='submit';actions.append(save);form.append(actions);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;const ok=await wsWrite(action==='rename'?'PATCH':'POST',{...extra,action,name:name.value,...(type?{type:type.value,config:readConfig()}:{})});if(ok)closeModal();else save.disabled=false};d.append(form);modal.replaceChildren(d);modal.classList.add('open');name.focus()}
function wsDraw(){const root=$('#workspaces');if(!root)return;root.replaceChildren();const shell=node('div',undefined,'ws-shell'),side=node('aside',undefined,'ws-side'),main=node('section',undefined,'ws-main');shell.append(side,main);root.append(shell);side.append(node('h3','Ambientes'));if(current?.is_admin)side.append(wsButton('+ Workspace',()=>wsCreate('workspace')));for(const w of wsState.workspaces){side.append(wsButton(w.name,()=>{wsId=w.id;boardId=null;wsDraw()},'ws-link'+(wsId===w.id?' selected':'')))}const boards=wsState.boards.filter(b=>b.workspace_id===wsId);if(!boards.some(b=>b.id===boardId))boardId=boards[0]?.id??null;side.append(node('h3','Quadros'));if(wsId&&current?.is_admin)side.append(wsButton('+ Quadro',()=>wsCreate('board',{workspace_id:wsId})));for(const b of boards)side.append(wsButton(b.name,()=>{boardId=b.id;wsDraw()},'ws-link'+(boardId===b.id?' selected':'')));const b=boards.find(b=>b.id===boardId);if(!b){main.append(node('h2','Seu espaço de trabalho'),node('p','Crie um workspace e um quadro para começar.','sub'));return}main.append(node('h2',b.name));const tools=node('div',undefined,'work-tools');if(can('create'))tools.append(wsButton('+ Registro',()=>wsCreate('item',{board_id:b.id}),'primary'));if(current?.is_admin){tools.append(wsButton('+ Campo',()=>wsCreate('field',{board_id:b.id})));tools.append(wsButton('+ Grupo',()=>wsCreate('group',{board_id:b.id})));}for(const [v,l] of [['table','Tabela'],['kanban','Kanban'],['calendar','Calendário'],['summary','Dashboard'],...(current?.is_admin?[['automations','Automações'],['workflows','Workflows']]:[])])tools.append(wsButton(l,()=>{wsMode=v;wsDraw()},'tab'+(wsMode===v?' active':'')));const search=node('input');search.placeholder='Buscar registros';search.value=wsQuery;search.setAttribute('aria-label','Buscar registros');tools.append(search);main.append(tools);const results=node('div',undefined,'work-grid');main.append(results);const groups=(wsState.groups||[]).filter(g=>g.board_id===b.id);const fields=wsState.fields.filter(f=>f.board_id===b.id),items=wsState.items.filter(i=>i.board_id===b.id);function draw(){results.replaceChildren();if(wsMode==='automations'&&current?.is_admin){wsAutomationPanel(results,b);return}if(wsMode==='workflows'&&current?.is_admin){wsWorkflowPanel(results,b);return}const filtered=items.filter(i=>i.title.toLocaleLowerCase().includes(wsQuery.toLocaleLowerCase()));const status=fields.find(f=>f.type==='status');
if(wsMode==='calendar'){const dates=fields.filter(f=>f.type==='date');if(!dates.length){results.append(node('p','Adicione um campo Data para usar o calendário.'));return}const selector=node('select');for(const f of dates){const o=node('option',f.name);o.value=f.id;selector.append(o)}const events=node('div',undefined,'calendar');results.append(selector,events);function display(){events.replaceChildren();const map=new Map();for(const i of filtered){const date=i.values?.[selector.value]||'Sem data';if(!map.has(date))map.set(date,[]);map.get(date).push(i)}for(const [date,rows] of [...map].sort(([a],[b])=>a.localeCompare(b))){const p=node('div',undefined,'period');p.append(node('h3',date==='Sem data'?date:date.split('-').reverse().join('/')));for(const i of rows)p.append(node('div',i.title,'event'));events.append(p)}}selector.onchange=display;display();return}
if(wsMode==='summary'){const stats=node('div',undefined,'stats');function metric(label,value){const c=node('div',undefined,'stat');c.append(node('span',label),node('strong',value));stats.append(c)}metric('Registros',String(filtered.length));if(status){const done=filtered.filter(i=>i.values?.[status.id]==='Concluído').length;metric('Concluídos',String(done));metric('Execução',Math.round(done/(filtered.length||1)*100)+'%')}for(const f of fields.filter(f=>['number','formula','rollup'].includes(f.type)))metric(f.name,filtered.reduce((sum,i)=>sum+(Number(i.values?.[f.id])||0),0).toLocaleString('pt-BR'));results.append(stats);if(status){const panel=node('div',undefined,'panel');panel.append(node('h2','Distribuição por status'));for(const stage of ['Sem status','A fazer','Em andamento','Concluído']){const count=filtered.filter(i=>(i.values?.[status.id]||'Sem status')===stage).length;const row=node('div',undefined,'report'),bar=node('div',undefined,'bar'),fill=node('i');fill.style.width=(count/(filtered.length||1)*100)+'%';bar.append(fill);row.append(node('b',stage),bar,node('span',String(count)));panel.append(row)}results.append(panel)}return}if(wsMode==='kanban'){if(!status){results.append(node('p','Adicione um campo Status para usar o Kanban.'));return}const grid=node('div',undefined,'board');for(const stage of ['Sem status','A fazer','Em andamento','Concluído']){const col=node('div',undefined,'col');col.append(node('h3',stage));for(const i of filtered.filter(i=>(i.values?.[status.id]||'Sem status')===stage)){const card=node('div',undefined,'card');card.append(node('b',i.title),wsCell(i,status));col.append(card)}grid.append(col)}results.append(grid);return}const table=node('table'),head=node('tr');head.append(node('th','Registro'),node('th','Grupo'));for(const f of fields)head.append(node('th',f.name));head.append(node('th','Ações'));const thead=node('thead');thead.append(head);table.append(thead);const tbody=node('tbody');for(const i of [...filtered].sort((a,b)=>(a.group_id??0)-(b.group_id??0))){const tr=node('tr');tr.append(node('td',i.title));const gtd=node('td'),gsel=node('select');gsel.setAttribute('aria-label','Grupo');for(const g of [{id:'',name:'Sem grupo'},...groups]){const o=node('option',g.name);o.value=g.id;gsel.append(o)}gsel.value=i.group_id??'';gsel.disabled=!can('edit');gsel.onchange=()=>wsWrite('PATCH',{action:'group_move',id:i.id,group_id:gsel.value?Number(gsel.value):null});gtd.append(gsel);tr.append(gtd);for(const f of fields){const td=node('td');td.append(wsCell(i,f));tr.append(td)}const td=node('td');if(can('edit'))td.append(wsButton('Editar nome',()=>wsCreate('rename',{id:i.id})));if(can('delete'))td.append(wsButton('Excluir',()=>{if(confirm('Excluir este registro?'))wsWrite('DELETE',{action:'item',id:i.id})}));tr.append(td);tbody.append(tr)}table.append(tbody);results.append(table);if(!filtered.length)results.append(node('p','Nenhum registro.','empty'))}search.oninput=()=>{wsQuery=search.value;draw()};draw()}
function wsCell(item,field){let v=item.values?.[field.id]??null,input;
 if(field.type==='relation'){const targets=(v||[]).map(id=>wsState.items.find(t=>t.id===id)?.title).filter(Boolean);const label=targets.join(', ')||'Vincular registros';return can('edit')?wsButton(label,()=>wsRelationEditor(item,field)):node('span',targets.join(', ')||'—')}
 if(['lookup','rollup','formula'].includes(field.type)){const display=x=>typeof x==='boolean'?(x?'Sim':'Não'):typeof x==='number'?x.toLocaleString('pt-BR',{maximumFractionDigits:6}):String(x);return node('span',Array.isArray(v)?v.map(display).join(', ')||'—':v===null?'—':display(v),'sub')}
if(field.type==='status'){input=node('select');for(const st of ['','A fazer','Em andamento','Concluído']){const o=node('option',st||'Sem status');o.value=st;input.append(o)}input.value=v??''}else{input=node('input');input.type=field.type==='text'?'text':field.type;input.setAttribute('aria-label',field.name);if(field.type==='checkbox')input.checked=Boolean(v);else input.value=v??'';if(field.type==='number')input.step='any';if(field.type==='text')input.maxLength=2000}input.disabled=!can('edit');input.onchange=()=>{const value=field.type==='checkbox'?input.checked:input.value===''?null:field.type==='number'?Number(input.value):input.value;input.disabled=true;wsWrite('PATCH',{action:'value',id:item.id,field_id:field.id,value})};return input}
